<!doctype html><html lang="es"><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;color:#263238;font-size:12px}h1{color:#174a7e}.box{border:1px solid #ccd5dd;padding:14px;margin:12px 0}dt{font-weight:bold;margin-top:8px}dd{margin:2px 0 8px}</style></head><body><h1>Ticket de Incidencia {{ $ticket->numero }}</h1><p>Sistema SGA · SLEP Andalién Costa</p><div class="box"><dl><dt>Incidencia</dt><dd>{{ config("centro_operaciones.incidencias.{$ticket->incidencia->tipo}.label", $ticket->incidencia->tipo) }}</dd><dt>Detalle</dt><dd>{{ $ticket->incidencia->descripcion ?: 'Sin detalle informado' }}</dd><dt>Establecimiento</dt><dd>{{ $ticket->incidencia->establecimiento?->nombre_establecimiento ?? '—' }}</dd><dt>Unidad responsable</dt><dd>{{ $ticket->unidad_departamento }}</dd><dt>Subdirección</dt><dd>{{ $ticket->subdireccion_dependencia }}</dd><dt>Responsable</dt><dd>{{ $ticket->responsable?->nombre_completo ?? '—' }}</dd><dt>Fecha de creación</dt><dd>{{ $ticket->created_at?->format('d/m/Y H:i') }}</dd><dt>Tiempo de resolución</dt><dd>Hasta el {{ $ticket->vence_en->format('d/m/Y H:i') }}</dd></dl></div></body></html>
